insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 3, 'Vós todos, habitantes do mundo, e vós, moradores da terra, vede quando for levantada a bandeira [nos] montes, e ouvi quando for tocada a trombeta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 4, 'Porque assim me disse o SENHOR: Estarei quieto olhando desde minha morada, como o calor ardente da luz do sol, como a nuvem de orvalho no calor da ceifa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 5, 'Porque antes da ceifa, quando a flor já se acabou, e as uvas brotam prestes a amadurecer, então ele podará as vides com a foice e, tendo cortado os ramos, ele os tirará [dali] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 6, 'Eles serão deixados juntos para as aves dos montes, e para os animais da terra; e sobre eles as aves passarão o verão, e todos os animais da terra passarão o inverno sobre eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 18, 7, 'Naquele tempo, será trazido um presente ao SENHOR dos exércitos por um povo alto e de pele lisa, e um povo temível desde seus territórios afora; uma nação dominadora e esmagadora, cuja terra rios dividem, ao lugar que pertence ao nome do SENHOR dos exércitos, ao monte de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 1, 'Revelação sobre o Egito: Eis que o SENHOR vem montado numa veloz nuvem, e ele virá ao Egito; e os ídolos do Egito tremerão perante sua presença; e o coração dos egípcios se derreterá dentro de si;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 2, 'Porque instigarei egípcios contra egípcios, e cada um lutará contra seu irmão, e cada um contra seu próximo; cidade contra cidade, reino contra reino.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 3, 'E o espírito dos egípcios se esvaziará dentro de si, e destruirei seu conselho; então eles perguntarão ao ídolos, encantadores, adivinhos que consultam espíritos de mortos, e feiticeiros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 4, 'E entregarei os egípcios nas mãos de um duro senhor, e um rei rigoroso dominará sobre eles,diz o SENHOR dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 5, 'E as águas do mar se acabarão; e o rio se esvaziará e se secará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 6, 'E os rios terão mau cheiro; os canais do Egito serão esvaziados e se secarão; as canas e os juncos murcharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 7, 'A relva junto ao rio, junto às margens dos rio, e todas as plantações junto ao rio se secarão, serão removidas, e se perderão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 8, 'E os pescadores gemerão e todos os que lançam anzol no rio lamentarão; e os que estendem rede sobre as águas perderão o ânimo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 9, 'E ficarão envergonhados os que trabalham com linho fino e os que tecem panos brancos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 10, 'Os fundamentos serão quebrados, e os empregados sentirão aflição na alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 11, 'Na verdade, os príncipes de Zoã são uns tolos; o conselho dos “sábios” de Faraó se tornou imprudente. Como é que dizeis a Faraó: Sou filho de sábios, sou descendente dos antigos reis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 12, 'Onde estão agora os teus sábios? Avisem-te, pois, e informem o que o SENHOR dos exércitos determinou contra o Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 13, 'Os príncipes de Zoã se tornaram tolos, os príncipes de Nofe estão enganados; e o Egito será levado ao erro pelos [que são] pedra de esquina de suas tribos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 14, 'O SENHOR derramou um espírito de confusão em seu interior, e levaram o Egito a errar em toda a sua obra, tal como o bêbado que se revolve em seu vômito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 15, 'E não haverá obra alguma que a cabeça ou a cauda, o ramo ou o junco, possa fazer para proveito do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 16, 'Naquele dia os egípcios serão como mulheres; e tremerão e temerão por causa do mover da mão do SENHOR dos exércitos, que moverá contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 17, 'E a terra de Judá será um assombro ao egípcios; todo aquele que dela lhe mencionarem, terá medo dentro de si, por causa da determinação do SENHOR dos exércitos, que determinou contra eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 18, 'Naquele dia haverá cinco cidades na terra do Egito que falem a língua de Canaã e prestem juramento ao SENHOR dos exércitos; uma delas será chamada Cidade da Destruição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 19, 'Naquele dia haverá um altar ao SENHOR no meio do Egito, e uma coluna ao SENHOR junto a sua fronteira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 20, 'E isso servirá como sinal e como testemunho ao SENHOR dos exércitos na terra do Egito; pois clamarão ao SENHOR por causa de seus opressores, e ele lhes mandará um salvador e defensor que os livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 21, 'E o SENHOR se fará conhecido no Egito, e os egípcios conhecerão ao SENHOR naquele dia; e eles o servirão [com] sacrifícios e ofertas, e farão votos ao SENHOR, e [os] cumprirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 22, 'E o SENHOR ferirá aos egípcios: ferirá mas [os] curará; e eles se converterão ao SENHOR, e ele aceitará suas orações, e os curará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 23, 'Naquele dia haverá uma estrada do Egito à Assíria; e os assírios virão ao Egito, e os egípcios à Assíria; e os egípcios prestarão culto junto com os assírios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 24, 'Naquele dia Israel será o terceiro entre o Egito e a Assíria, uma bênção no meio da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 19, 25, 'Porque o SENHOR dos exércitos os abençoará, dizendo: Bendito seja o meu povo do Egito, e a Assíria, obra de minhas mãos, e Israel, minha herança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 20, 1, 'No ano em que o general enviado por Sargom, rei da Assíria, veio a Asdode, guerreou contra Asdode, e a tomou,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 20, 2, 'Naquele tempo o SENHOR falou por meio de Isaías, filho de Amoz, dizendo: Vai, tira a roupa de saco de teus lombos, e descalça a sandália de teus pés.E assim ele fez, andando nu e descalço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 20, 3, 'Então o SENHOR disse: Assim como meu servo Isaías anda nu e descalço, [como] sinal e presságio relativo ao Egito e a Cuxe,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 20, 4, 'assim o rei da Assíria levará em cativeiro a prisioneiros do Egito e a prisioneiros de Cuxe, tanto jovens, como velhos, nus e descalços, e descobertas as nádegas, para envergonhar ao Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 20, 5, 'E terão medo e vergonha por causa de Cuxe, em quem esperavam, e por causa do Egito, no qual se orgulhavam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 20, 6, 'E os moradores do litoral dirão naquele dia: Vede [o que houve com] aqueles em quem esperávamos, a quem buscávamos socorro, para nos livrarmos da presença do rei da Assíria! E [agora] ,como escaparemos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 1, 'Revelação sobre o deserto do mar:Assim como os turbilhões de vento passam pelo Negueve, assim algo vem do deserto, de uma terra temível.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 2, 'Uma visão terrível me foi informada: o enganador engana, e o destruidor destrói. Levanta-te, Elão! Faze o cerco, Média! [Pois] estou pondo fim em todos os gemidos que ela [causou] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 3, 'Por isso meus lombos estão cheios de sofrimento; fui tomado por dores, tais como as dores de parto; fiquei perturbado ao ouvir, e estou horrorizado de ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 4, 'Meu coração se estremece, o terror me apavora; o anoitecer, que eu desejava, [agora] me causa medo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 5, 'Eles preparam a mesa, estendem tapetes, comem e bebem. Levantai-vos, príncipes! Passai óleo nos escudos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 6, 'Porque assim me disse o Senhor: Vai, põe um vigilante, [e] ele diga o que estiver vendo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 7, 'Caso ele veja uma carruagem, um par de cavaleiros, pessoas montadas em asnos, [ou] pessoas montadas em camelos, ele deve prestar atenção, muita atenção.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 8, 'E ele gritou [como] um leão: Senhor, na torre de vigia estou continuamente de dia; e em minha guarda me ponho durante noites inteiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 9, 'E eis que está vindo uma carruagem de homens, um par de cavaleiros.Então ele respondeu: Caiu! Caiu a Babilônia, e todas as imagens esculpidas de seus deuses foram quebradas contra a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 10, 'Ó meu [povo] debulhado por batidas, e trigo de minha eira! O que ouvi do SENHOR dos exércitos, Deus de Israel, isso eu vos disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 11, 'Revelação sobre Dumá: Alguém está gritando de Seir. Guarda, o que houve de noite? Guarda, o que houve de noite?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 12, 'O guarda disse: Vem a manhã, e também a noite; se quereis perguntar, perguntai; voltai-vos, e vinde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 13, 'Revelação sobre a Arábia:Nos matos da Arábia passareis a noite, ó caravanas de dedanitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 14, 'Saí ao encontro dos sedentos com água; os moradores da terra de Temá com seu pão encontram aos que estavam fugindo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 15, 'Pois fogem de diante de espadas, de diante da espada desembainhada, e diante do arco armado, e de diante do peso da guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 16, 'Porque assim me disse o Senhor: Dentro de um ano (tal como ano de empregado), será arruinada toda a glória de Quedar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 21, 17, 'E os que restarem do número de flecheiros, os guerreiros dos filhos de Quedar, serão reduzidos a poucos.Pois assim disse o SENHOR, Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 1, 'Revelação sobre o vale da visão:O que há contigo, agora, para que tenhas subido toda aos terraços?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 2, 'Tu cheia de barulhos, cidade tumultuada, cidade alegre! Teus mortos não morreram pela espada, nem morreram na guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 3, 'Todos os teus líderes juntamente fugiram; foram presos sem [nem usarem] o arco; todos os teus que foram achados juntamente foram amarrados, [ainda que] tenham fugido para longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 4, 'Por isso eu disse: Desviai vossa vista de mim, [pois] chorarei amargamente; não insistais em me consolar pela destruição da filha do meu povo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 5, 'Pois foi dia de alvoroço, de atropelamento, e de confusão, proveniente do Senhor DEUS dos exércitos, no vale da visão; [dia] de muros serem derrubados, e de gritarem ao monte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 6, 'E Elão tomou a aljava, [e] houve homens em carruagens, e cavaleiros. Quir descobriu os escudos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 7, 'E foi que teus melhores vales se encheram de carruagens de guerra; e cavaleiros se puseram em posição de ataque junto ao portão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 8, 'E tiraram a cobertura de Judá; e naquele dia olhastes para as armas da casa do bosque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 9, 'E vistes as brechas [dos muros] da cidade de Davi, que eram muitas; e ajuntastes águas no tanque de baixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 10, 'Também contastes as casas de Jerusalém; e derrubastes casas para fortalecer os muros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 11, 'Fizestes também um reservatório entre os dois muros para as águas do tanque velho; porém não destes atenção para aquele que fez estas coisas, nem olhastes para aquele que as formou desde a antiguidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 12, 'E naquele dia o Senhor DEUS dos exércitos chamou ao choro, ao lamento, ao raspar de cabelos, e ao vestir de saco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 13, 'E eis aqui alegria e festejo, matando vacas e degolando ovelhas, comendo carne, bebendo vinho, [e dizendo] : Comamos e bebamos, porque amanhã morreremos!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 14, 'Mas o SENHOR dos exércitos se revelou a meus ouvidos, [dizendo] : Certamente esta maldade não vos será perdoada até que morrais, diz o Senhor DEUS dos exércitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 15, 'Assim disse o Senhor DEUS dos exércitos: Vai, visita este mordomo, Sebna, que administra a casa [real] ,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 16, '[E dize-lhe] : O que é que tens aqui? Ou quem tu tens aqui, [que te dá direito] a cavares aqui tua sepultura, [como] quem cava em lugar alto sua sepultura, e talha na rocha morada para si?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 17, 'Eis que o SENHOR te lançará fora, ó homem, e te agarrará!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 18, 'Certamente ele te lançará rodando, como uma bola numa terra larga e espaçosa. Ali morrerás, e ali [estarão] tuas gloriosas carruagens, [para] desonra da casa do teu senhor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 19, 'E te removerei de tua posição, e te arrancarei de teu assento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 20, 'E será naquele dia, que chamarei a meu servo Eliaquim, filho de Hilquias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 21, 'E eu o vestirei com tua túnica, e porei nele o teu cinto, e entregarei teu governo nas mãos dele, e ele será como um pai aos moradores de Jerusalém e à casa de Judá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 22, 'E porei a chave da casa de Davi sobre seu ombro; quando ele abrir, e ninguém fechará; e quando ele fechar, ninguém abrirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 23, 'E eu o fincarei [como] a um prego em um lugar firme; e ele será um trono de honra à casa de seu pai.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 24, 'E nele pendurarão toda a honra da casa de seu pai, dos renovos e dos descendentes, todos as vasilhas menores; desde as vasilhas de taças, até todas as vasilhas de jarros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 22, 25, 'Naquele dia, - diz o SENHOR dos exércitos, - o prego fincado em lugar firme será tirado; e será cortado, e cairá; e a carga que nele está será cortada; porque [assim] o SENHOR disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 1, 'Revelação sobre Tiro:Uivai, navios de Társis, pois ela está arruinada, sem sobrar casa alguma, nem entrada [nela] . Desde a terra do Chipre isto [lhes] foi informado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 2, 'Calai-vos, moradores do litoral; vós mercadores de Sidom, que vos enchíeis [pelos] que atravessavam o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 3, 'E sua renda era os grãos de Sior, a colheita do Nilo, [que vinha] por muitas águas. Ela era o centro de comércio das nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 4, 'Envergonha-te, Sidom; pois o mar falou, a fortaleza do mar disse: Eu não tive dores de parto, nem de mim nasceu criança; nunca criei meninos nem eduquei virgens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 5, 'Quando as notícias [chegarem] ao Egito, eles se angustiarão com as informações de Tiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 6, 'Passai-vos a Társis; uivai, moradores do litoral!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 7, 'É esta a vossa alegre cidade? A que existia desde os tempos antigos? Eram os pés dela que a levavam para alcançar lugares distantes?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 8, 'Quem foi, pois, que determinou isto contra Tiro, a que dava coroas, que cujos mercadores eram príncipes, e cujos comerciantes eram os mais ilustres da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 9, 'Foi o SENHOR dos exércitos que determinou isto, para envergonhar o orgulho de sua beleza, e humilhar a todos os ilustres da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 10, 'Passa-te como o rio à tua terra, ó filha de Társis, [pois] já não há mais fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 11, 'Ele estendeu sua mão sobre o mar, [e] abalou aos reinos; o SENHOR deu uma ordem contra Canaã, para destruir suas fortalezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 12, 'E disse: Nunca mais te encherás de alegria, ó oprimida virgem, filha de Sidom; levanta-te, passa ao Chipre; e alinda ali não terás descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 13, 'Olhai para a terra dos Caldeus, este que deixou de ser povo. A Assíria a fundou para os que moravam no deserto; levantaram suas fortalezas, e derrubaram seus palácios; transformou-a em ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 14, 'Uivai, navios de Társis; porque destruída está vossa fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 15, 'E será naquele dia, que Tiro será esquecida por setenta anos, como dias de um rei; [mas] ao fim de setenta anos, haverá em Tiro [algo] como a canção da prostituta:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 16, 'Toma uma harpa, rodeia a cidade, ó prostituta esquecida; toca boa música, [e] canta várias canções, para que tu sejas lembrada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 17, 'Pois será que, ao fim de setenta anos, o SENHOR visitará a Tiro, e voltará à sua atividade, prostituindo-se com todos os reinos do mundo que há sobre a face da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 23, 18, 'Mas seu comércio e seus ganhos como prostituta serão consagrados ao SENHOR; não serão guardados nem depositados; mas seu comércio será para os que habitam perante o SENHOR, para que comam até se saciarem, e tenham roupas de boa qualidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 1, 'Eis que o SENHOR esvazia a terra, e a assola; e transtorna sua superfície, e espalha seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 2, 'E [isso] acontecerá, tanto ao povo, como ao sacerdote; tanto ao servo, como a seu senhor; tanto à serva, como a sua senhora; tanto ao comprador, como ao vendedor; tanto a quem empresta, como ao que toma emprestado; tanto ao credor, como ao devedor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 3, 'A terra será esvaziada por completo, e será saqueada por completo; pois o SENHOR pronunciou esta palavra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 4, 'A terra chora [e] se murcha; o mundo enfraquece [e] se murcha; estão enfraquecidos os mais elevados do povo da terra;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 5, 'Pois a terra está contaminada por causa de seus moradores; pois transgridem as leis, mudam os estatutos, [e] anulam o pacto eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 6, 'Pois isso, a maldição consome a terra; e os que nela habitam pagam por sua culpa; por isso serão queimados os moradores da terra, e poucos homens restarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 7, 'O suco de uva chora, a vinha se enfraquece; todos os alegres de coração [agora] suspiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 8, 'A alegria dos tamborins parou, acabou o ruído dos que saltavam de prazer; a alegria da harpa parou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 9, 'Não beberão vinho com canções; a bebida alcoólica será amarga aos que a beberem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 10, 'A cidade da confusão está quebrada; todas as casas estão fechadas; ninguém pode entrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 11, 'Um clamor de lamento por causa do vinho [se ouve] nas ruas; toda a alegria se escureceu; o prazer da terra sumiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 12, '[Só] restou assolação na cidade; o portão foi feito em ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 13, 'Porque assim será por entre a terra, e no meio destes povos; como quando se sacode a oliveira, [e] como as uvas que sobram depois de terminada a vindima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 14, 'Eles levantarão sua voz, e cantarão com alegria; por causa da glória do SENHOR, gritarão de alegria desde o mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 15, 'Por isso glorificai ao SENHOR no oriente; [e] no litoral ao nome do SENHOR, o Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 16, 'Dos confins da terra ouvimos canções [para] a glória do Justo; mas eu digo: Fraqueza minha, fraqueza minha; ai de mim! Os enganadores enganam, e com enganação os enganadores agem enganosamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 17, 'Temor, cova e laço [vem] sobre ti, ó morador da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 18, 'E será que, aquele que fugir do som de temor cairá na cova; e aquele que subir da cova, o laço o prenderá; pois as janelas do alto se abrem; e os fundamentos da terra tremerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 19, 'A terra será quebrada por completo; a terra será totalmente partida, e será muito abalada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 20, 'A terra balançará como um bêbado; e será abalada como uma choupana; e sua transgressão pesará sobre ela; cairá, e nunca mais se levantará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 21, 'E será que naquele dia o SENHOR visitará [para punir] aos exércitos do alto na altura, e aos reis da terra sobre a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 22, 'E juntamente serão amontoados [como] presos numa masmorra; e serão encarcerados num cárcere; e muitos dias depois serão visitados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 24, 23, 'E a lua será envergonhada, e o sol humilhado, quando o SENHOR dos exércitos reinar no monte de Sião, e em Jerusalém; e então perante seus anciãos [haverá] glória.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 1, 'Ó SENHOR, tu és meu Deus; eu te exaltarei, [e] louvarei o teu nome, pois tu tens feito maravilhas, [teus] conselhos antigos, [com] fidelidade e verdade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 2, 'Pois tu fizeste da cidade um amontoado de pedras; da cidade fortificada uma ruína; [fizeste com que] os edifícios dos estrangeiros deixassem de ser cidade, e nunca mais voltem a ser construídos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 3, 'Por isso, um poderoso povo te glorificará, a cidade de nações terríveis te temerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 4, 'Pois tu foste a fortaleza do pobre, a fortaleza do necessitado, em sua angústia; refúgio contra a tempestade, [e] sombra contra o calor; porque o sopro dos violentos é como uma tempestade contra o muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 5, 'Tal como o calor em lugar seco, assim tu abaterás o ímpeto dos estrangeiros; tal como uma espessa nuvem [diminui] o calor, assim será humilhada a canção dos violentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 6, 'E neste monte o SENHOR dos exércitos fará para todos os povos um banquete de animais cevados, um banquete de vinhos finos; de gorduras de tutanos, e de vinhos finos, bem purificados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 7, 'E neste monte devorará o véu funerário que está sobre todos os povos, e a coberta com que todas as nações se cobrem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 8, 'Ele devorará a morte para sempre, e o Senhor DEUS enxugará as lágrimas de todos os rostos; e tirará a humilhação de seu povo de toda a terra; pois o SENHOR [assim] disse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 9, 'E naquele dia se dirá: Eis que este é o nosso Deus, em quem temos posto nossa esperança para nos salvar; este é o SENHOR, em quem esperamos; em sua salvação teremos prazer e nos alegraremos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 10, 'Pois a mão do SENHOR descansará neste monte; Moabe, porém, será esmagado debaixo dele, tal como se esmaga a palha no amontoado de esterco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 11, 'E estenderão suas mãos no meio dela, tal como um nadador estende para nadar; e [o SENHOR] abaterá a arrogância deles com a habilidade de suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 25, 12, 'E lançará abaixo as fortalezas de teus muros; ele [as] abaterá e derrubará até o chão, ao pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 1, 'Naquele dia, se cantará este cântico na terra de Judá: Temos uma cidade forte! [Deus lhe] pôs a salvação por muros e antemuros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 2, 'Abri as portas, para que por elas entre a nação justa, que guarda fidelidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 3, 'Tu guardarás em completa paz aquele que tem firme entendimento, pois ele confia em ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 4, 'Confiai no SENHOR para sempre, pois no SENHOR DEUS está a rocha eterna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 5, 'Pois ele abate aos que habitam em lugares altos, a cidade elevada; certamente ele a abaixará até o chão, e a derrubará até o pó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 6, 'Pés a pisotearão; os pés dos afligidos, os passos dos pobres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 7, 'O caminho do justo é todo plano; tu [que és] reto nivelas o andar do justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 8, 'Também no caminho dos teus juízos esperamos em ti; em teu nome e em tua lembrança está o desejo de [nossa] alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 9, 'Com minha alma te desejei de noite, e [com] meu espírito dentro de mim te busquei de madrugada; pois quando teus juízos [estão] sobre a terra, os moradores do mundo aprendem a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 10, '[Ainda] que se faça favor ao perverso, nem assim ele aprende a justiça; [até] na terra dos corretos ele pratica maldade, e não dá atenção à majestade do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 11, 'Ó SENHOR, tua mão está levantada, mas eles não [a] veem; [porém] eles verão e serão envergonhados pelo zelo [que tens] do [teu] povo; e o fogo consumirá a teus adversários.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 12, 'Ó SENHOR, tu nos fornecerá paz; pois todos os nossos feitos tu fizeste por nós.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 13, 'Ó SENHOR nosso Deus, outros senhores fora de ti nos dominaram; mas somente em ti, em teu nome, mantínhamos nossos pensamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 14, 'Eles estão mortos, não [voltarão] a viver; fantasmas não ressuscitarão; por isso tu os visitaste e os destruíste, e eliminaste toda a memória deles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 15, 'Tu, SENHOR, engrandeceste esta nação; engrandeceste esta nação, [e] te fizeste glorioso; alargaste os limites da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 16, 'Ó SENHOR, na aflição eles te buscaram; [quando] tu os castigaste, uma oração eles sussurraram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 17, 'Tal como a grávida quando chega a hora do parto, sofre e dá gritos por suas dores, assim fomos nós diante de tua presença, SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 18, 'Concebemos e tivemos dores, porém geramos [nada além] de vento. Não trouxemos libertação à terra, nem os moradores do mundo caíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 19, 'Os teus mortos viverão, [junto com] meu cadáver, [assim] ressuscitarão; festejai e sede alegres, vós que habitais no pó! Pois o teu orvalho [é] orvalho de luz, e a terra gerará de si [seus] mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 20, 'Vai, ó povo meu; entra em teus quartos, e fecha tuas portas ao redor de ti; esconde-te por um momento, até que a ira tenha passado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 26, 21, 'Porque eis que o SENHOR sairá de seu lugar para punir a maldade dos moradores da terra sobre eles; e a terra mostrará seus sangues, e não mais cobrirá seus mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 1, 'Naquele dia, o SENHOR punirá, com sua dura, grande e forte espada, ao Leviatã, a ágil serpente; ao Leviatã, a serpente tortuosa; e matará o dragão que está no mar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 2, 'Naquele dia, cantai à preciosa vinha:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 3, 'Eu, o SENHOR, a vigio, e a rego a cada momento; para que ninguém a invada, eu a vigiarei de noite e de dia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 4, '[Já] não há furor em mim. Caso alguém ponha contra mim espinhos e cardos, eu lutarei contra eles em batalha, e juntos os queimarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 5, 'Ou, se quiserem depender de minha força, então façam as pazes comigo, e sejam comigo feitas as pazes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 6, '[Dias] virão em que Jacó lançará raízes, florescerá, e brotará Israel; e encherão superfície do mundo de frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 7, 'Por acaso ele o feriu, como feriu aos que o feriram? Ou ele o matou, como morreram os que o por ele foram mortos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 8, 'Com moderação brigaste contra ela, quando a rejeitaste; [quando] a tirou com seu vento forte, no dia do vento do Oriente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 9, 'Portanto assim será perdoada a maldade de Jacó, e este será o fruto completo da remoção de seu pecado: quando tornar todas as pedras dos altares como pedras de cal despedaçadas, [e] os mastros de Aserá e os altares de incenso não ficarem mais de pé.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 10, 'Pois a cidade fortificada [será] abandonada, o lugar de habitação deixado e desabitado como o deserto; ali os bezerros pastarão, e ali se deitarão e comerão seus ramos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 11, 'Quando seus ramos se secarem, serão quebrados; mulheres virão, e os queimarão; pois este povo não tem entendimento. Por isso, aquele que o criou não terá compaixão dele; aquele que o formou não lhe concederá graça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 12, 'E será naquele dia, que o SENHOR debulhará o trigo, desde o rio [Eufrates] até o ribeiro do Egito; porém vós, filhos de Israel, sereis colhidos um a um.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 27, 13, 'E será naquele dia, que uma grande trombeta será tocada; então os que estiverem perdidos na terra da Assíria e os que tiverem sido lançados à terra do Egito voltarão, e adorarão ao SENHOR no monte santo em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 1, 'Ai da coroa de arrogância dos bêbados de Efraim, cujo belo ornamento é [como] uma flor que murcha, que está sobre a cabeça do vale fértil dos derrotados pelo vinho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 2, 'Eis que o Senhor tem um valente e poderoso, [que vem] como tempestade de granizo, tormenta destruidora; e como tempestade de impetuosas águas que inundam; com [sua] mão ele [os] derrubará em terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 3, 'A coroa de arrogância dos bêbados de Efraim será pisada sob os pés.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 4, 'E o seu belo ornamento, que está sobre a cabeça do vale fértil, será como a flor que murcha; como o primeiro fruto antes do verão, que, quando alguém o vê, pega e o come.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 5, 'Naquele dia o SENHOR dos exércitos será por coroa gloriosa, e por bela tiara, para os restantes de seu povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 6, 'E por espírito de juízo, para o que se senta para julgar, e por fortaleza aos que fazem a batalha recuar até a porta [da cidade] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 7, 'Mas também estes vacilam com o vinho, e com a bebida alcoólica perdem o caminho: o sacerdote e o profeta vacilam com a bebida alcoólica, foram consumidos pelo vinho; perdem o caminho pela bebida forte, andam confusos na visão, [e] tropeçam no ato de julgar;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 8, 'Pois todas as [suas] mesas estão cheias de vômito; não há lugar que não haja imundície.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 9, 'A quem ele ensinará o conhecimento? E a quem se explicará a mensagem? A bebês recém-desmamados de leite, tirados dos peitos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 10, 'Pois [tudo] tem sido mandamento sobre mandamento, mandamento sobre mandamento, regra sobre regra, regra sobre regra; um pouco aqui, um pouco ali.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 11, 'Pois por lábios estranhos e por língua estrangeira se falará a este povo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 12, 'Ao qual dissera: Este é o [lugar de] descanso; dai descanso ao cansado; e este é o repouso; porém não quiseram ouvir.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 13, 'Assim, pois, a palavra do SENHOR lhes será mandamento sobre mandamento, mandamento sobre mandamento, regra sobre regra, regra sobre regra; um pouco aqui, um pouco ali; para que vão, e caiam para trás, e se quebrem, e sejam enlaçados e capturados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 14, 'Portanto ouvi a palavra do SENHOR, vós homens escarnecedores, dominadores deste povo, que está em Jerusalém;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 15, 'Pois dizeis: Fizemos um pacto com a morte, e com o Xeol fizemos um acordo: quando passar a abundância de açoites, não chegará a nós; pois pusemos a mentira como nosso refúgio, e sob a falsidade nos escondemos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 16, 'Por isso, assim diz o Senhor DEUS: Eis que eu fundo em Sião uma pedra; uma pedra provada, pedra preciosa de esquina, firmemente fundada; quem crer, não precisará fugir às pressas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 17, 'E porei o juízo como linha de medida, e a justiça como prumo; o granizo varrerá o refúgio da mentira, e as águas inundarão o esconderijo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 18, 'E vosso pacto com a morte se anulará, e vosso acordo com o Xeol não será cumprido; e quando a abundância de açoites passar, então por ela sereis esmagados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 19, 'Logo que começar a passar, ela vos tomará, porque todas as manhãs passará, de dia e de noite; e será que só de ser dada a notícia, [já] haverá aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 20, 'Porque a cama será tão curta, que [ninguém] poderá se estender nela; e o cobertor tão estreito, que [ninguém] poderá se cobrir com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 21, 'Porque o SENHOR se levantará como no monte de Perazim, e se enfurecerá como no vale de Gibeão, para fazer sua obra, sua estranha obra; e operar seu ato, seu estranho ato.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 22, 'Agora, pois, não escarneçais, para que vossas cordas não vos prendam com ainda mais força; pois eu ouvi do Senhor DEUS dos exércitos sobre uma destruição que já foi determinada sobre toda a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 23, 'Inclinai os ouvidos, e ouvi minha voz; prestai atenção, e ouvi o que eu digo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 24, 'Por acaso o lavrador lavra o dia todo para semear, [ou] fica [o dia todo] abrindo e revolvendo a sua terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 25, 'Quando ele já igualou sua superfície, por acaso ele não espalha endro, e derrama cominho, ou lança do melhor trigo, ou cevada escolhida, ou centeio, [cada qual] em seu lugar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 26, 'Pois seu Deus o ensina, instruindo sobre o que se deve fazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 27, 'Porque o endro não é debulhado com uma marreta pesada, nem sobre o cominho se passa por cima com uma roda de carroça; em vez disso, com uma vara se separa os grãos de endro, e com um pau os de cominho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 28, 'O trigo é triturado, mas não é batido para sempre; ainda que seja esmagado com as rodas de sua carroça, ele não é triturado com seus cavalos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 28, 29, 'Até isto procede do SENHOR dos exércitos. Ele é maravilhoso em conselhos, [e] grande em sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 1, 'Ai de Ariel! Ariel, a cidade [em que] Davi se acampou. Acrescentai ano a ano, completem-se as festas de sacrifícios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 2, 'Contudo oprimirei a Ariel, e haverá pranto e tristeza; e [ela] me será como um altar de sacrifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 3, 'Pois eu me acamparei ao seu redor, e te cercarei com rampas, e levantarei cercos contra ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 4, 'Então serás abatida; falarás junto ao chão, e tua fala será fraca desde o pó da terra, como a de um morto, e tua fala sussurrará desde o pó da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 5, 'E a multidão de teus adversários será como o pó fino, e a multidão dos violentos como a palha que passa; e [isto] acontecerá de repente, em um momento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 6, 'Pelo SENHOR dos exércitos serás visitada com trovões, terremotos, e grande ruído; com impetuoso vento, tempestade, e labareda de fogo consumidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 7, 'E tal como um sonho ou visão noturna, [assim] será a multidão de todas as nações que batalharão contra Ariel, [assim] também como todos os que lutaram contra ela e seus muros, e a oprimiram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 8, 'Será também como um faminto que sonha estar comendo, porém, ao acordar, sua alma está vazia; ou como o sedento que sonha estar bebendo, porém, ao acordar, eis que está fraco e com sede na alma; assim será toda a multidão de nações que batalharem contra o monte de Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 9, 'Parai, e maravilhai-vos; cegai-vos, e sede cegos! Estão bêbados, mas não de vinho; cambaleiam, mas não por bebida alcoólica.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 10, 'Pois o SENHOR derramou sobre vós espírito de sono profundo; ele fechou vossos olhos (os profetas), e cobriu vossos cabeças (os videntes).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 11, 'E toda visão vos será como as palavras de um livro selado que, quando se dá a um letrado, dizendo: Lê isto, por favor;Esse dirá: Não posso, porque está selado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 12, 'E quando se dá o livro a alguém que não saiba ler, dizendo: Lê isto, por favor; Esse dirá: Não sei ler.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 13, 'Pois o Senhor disse: Visto que este povo se aproxima [de mim] com a boca, e me honram com seus lábios, porém seus corações se afastam de mim, e [fingem que] me temem por meio de mandamentos humanos que aprendem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 14, 'Por isso, eis que continuarei a fazer coisas espantosas com este povo; coisas espantosas e surpreendentes; porque a sabedoria de seus sábios perecerá, e a inteligência dos inteligentes se esconderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 15, 'Ai dos que querem se esconder do SENHOR, encobrindo [suas] intenções; e fazem suas obras às escuras, e dizem: Quem nos vê? Quem nos conhece?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 16, '[Como é grande] vossa perversão! Pode, por acaso, o oleiro ser considerado igual ao barro? Pode a obra dizer de seu criador que “ele não me fez”? Ou o vaso formado dizer de seu formador: “Ele nada entende”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 17, 'Por acaso não [será que] ,daqui a pouco tempo, o Líbano se tornará um campo fértil? E o campo fértil será considerado uma floresta?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 18, 'E naquele dia os surdos ouvirão as palavras do livro; e os olhos dos cegos desde a escuridão e desde as trevas as verão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 19, 'E os mansos terão cada vez mais alegria no SENHOR; e os necessitados entre os homens se alegrarão no Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 20, 'Pois os violentos serão eliminados, e os zombadores serão consumidos; e todos os que gostam de maldade serão extintos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 21, 'Os que acusam aos homens por meio de palavras, e armam ciladas contra quem [os] repreende na porta [da cidade] ,e os que prejudicam ao justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 22, 'Portanto, assim o Senhor DEUS, que libertou a Abraão, diz à casa de Jacó: Jacó não será mais envergonhado, nem seu rosto ficará pálido,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 23, 'Pois quando ele vir seus filhos, obra de minhas mãos, no meio de si, [então] santificarão ao meu nome; santificarão ao Santo de Jacó, e temerão ao Deus de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 29, 24, 'E os confusos de espírito virão a ter entendimento, e os murmuradores aprenderão doutrina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 1, 'Ai dos filhos rebeldes!,diz o SENHOR, Eles, que tomam conselho, mas não de mim; que fazem um pacto, porém sem o meu Espírito, para acrescentarem pecado sobre pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 2, 'Eles, que descem ao Egito sem me perguntarem, para se fortificarem com a força de Faraó, e confiarem estar protegidos na sombra do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 3, 'Entretanto, a força de Faraó se tornará vossa vergonha, e a confiança na sombra do Egito [será] humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 4, 'Ainda que seus príncipes estejam em Zoã, e seus embaixadores tenham chegado a Hanes,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 5, 'Todos se envergonharão por causa de um povo que em nada lhes será útil, nem de ajuda, nem de proveito; mas, ao invés disso, [lhes será] vergonha e humilhação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 6, 'Revelação sobre os animais selvagens do deserto de Negueve: Por entre uma terra da aflição e da angústia, de onde [vem] o leão forte, o leão velho, a cobra e a serpente voadora, eles levam seus bens nas costas de jumentos, e seus tesouros sobre corcovas de camelos, a um povo que em nada [lhes] será útil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 7, 'Porque o Egito [os] ajudará em vão, e inutilmente. Por isso, a este eu tenho chamado: “Raabe, que nada faz”.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 8, 'Agora vai, [e] escreve isso numa placa na presença deles, e registra isso num livro, para que dure até o último dia, para todo o sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 9, 'Porque eles são um povo rebelde, são filhos mentirosos, filhos que não querem ouvir a Lei do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 10, 'Que dizem aos videntes: Não tenhais visões, e aos profetas: Não nos reveleis o que é correto! Dizei coisas agradáveis para nós, revelai ilusões!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 11, 'Desviai-vos do caminho, afastai-vos da vereda! Deixai de nos fazer deparar com o Santo de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 12, 'Portanto, assim diz o Santo de Israel: Visto que rejeitais esta palavra, e vós confiais na opressão e no engano, e nisto vos apoiais,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 13, 'por isso esta maldade vos será como uma rachadura, prestes a cair, que já encurva um alto muro, cuja queda será repentina e rápida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 14, 'E será quebrado como a quebra de um vaso de oleiro, tão esmigalhado que nada se preservará; não se poderá achar um caco sequer entre seus pedacinhos que sirva para transportar brasas de uma fogueira, ou tirar água de um tanque.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 15, 'Pois assim diz o Senhor DEUS, o Santo de Israel: Com arrependimento e descanso, ficaríeis livres; com calma e confiança teríeis força; mas vós não quisestes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 16, 'Ao invés disso, dissestes: Não, é melhor fugirmos sobre cavalos. Cavalgaremos em rápidos cavalos! Por isso vós fugireis, mas vossos perseguidores serão [ainda mais] rápidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 17, 'Ao grito de um, mil [fugirão] ,[e] ao grito de cinco, [todos] vós fugireis; até que sejais deixados [solitários] ,como um mastro no cume do monte, como uma bandeira num morro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 18, 'Por isso o SENHOR esperará para ter piedade de vós; e por isso ele se exaltará, para se compadecer de vós; pois o SENHOR é Deus de juízo; bem-aventurados todos os que nele esperam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 19, 'Pois o povo habitará em Sião, em Jerusalém; certamente não continuarás a chorar; ele terá piedade de ti sob a voz do teu clamor; quando a ouvir, ele te responderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 20, 'De fato, o Senhor vos dará pão de angústia, e água de opressão; porém teus instrutores nunca mais se esconderão de ti; ao contrário, teus olhos verão os teus instrutores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 21, 'E quando virardes para a direita ou para a esquerda, teus ouvidos ouvirão a palavra [do que] está atrás de ti, dizendo: Este é o caminho; andai por ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 22, 'E considerarás tuas esculturas recobertas de prata e tuas imagens revestidas de ouro como impuras; tu as jogarás fora como se fossem panos imundos, e dirás a cada uma delas: Fora daqui!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 23, 'Então ele dará chuva sobre tuas sementes que tu tiveres semeado a terra, assim como pão produzido da terra; e esta será fértil e farta; naquele dia teu gado pastará em grandes pastos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 24, 'Os bois e os jumentos que lavram a terra comerão forragem de boa qualidade, limpa com a pá e o forcado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 25, 'E em todo monte alto e todo morro elevado haverá ribeiros e correntes de águas, no dia da grande matança, quando as torres caírem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 26, 'E a luz da lua será como a luz do sol, e a luz do sol será sete vezes maior, como a luz de sete dias, quando o SENHOR atar a fratura de seu povo, e curar a chaga de sua ferida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 27, 'Eis que o nome do SENHOR vem de longe; sua ira está ardendo, e a carga é pesada; seus lábios estão cheios de ira, e sua língua está como um fogo consumidor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 28, 'E seu sopro como um rio que inunda, chegando até o pescoço, para sacudir as nações com a peneira da inutilidade; e um freio nos queixos dos povos [os] fará andar perdidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 29, 'Um cântico haverá entre vós, tal como na noite em que se santifica uma festa; haverá também alegria de coração, tal como aquele que anda com uma flauta para vir ao monte do SENHOR, à Rocha de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 30, 'E o SENHOR fará com que ouçam a glória de sua voz, e com que vejam a descida de seu braço, com indignação de ira, e labareda de fogo consumidor, raios, tempestade, e pedra de granizo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 31, 'Pois com a voz do SENHOR, a Assíria será feita em pedaços; ele [a] ferirá com a vara.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 32, 'E será que, em todos os golpes do bordão da firmeza que o SENHOR lhe der, será [acompanhado] de tamborins e harpas; e com ataques agitados ele a atacará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 30, 33, 'Pois Tofete já está preparada desde muito tempo, e já está pronta para o rei; ele a fez profunda e larga; sua pira tem muito fogo e lenha; o sopro do SENHOR, como uma correnteza de enxofre, a acenderá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 1, 'Ai dos que descem ao Egito em busca de ajuda, e põem sua esperança em cavalos, e confiam em carruagens, por serem muitas, e em cavaleiros, por serem fortes; e não dão atenção ao Santo de Israel, nem buscam ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 2, 'Porém ele é sábio também; ele fará vir o mal, e não volta atrás em suas palavras; ele se levantará contra a casa dos malfeitores, e contra a ajuda dos que praticam perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 3, 'Pois os egípcios não são Deus, mas sim, homens; seus cavalos são carne, e não espírito; e o SENHOR estenderá sua mão, e fará tropeçar o que ajuda, e cair o ajudado; e todos juntos serão consumidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 4, 'Porque assim me disse o SENHOR: Tal como o leão e o filhote de leão rugem sobre sua presa, ainda que contra ele seja chamada uma multidão de pastores; ele não se espanta por suas vozes, nem se intimida por seu grande número; assim também o SENHOR dos exércitos descerá para lutar sobre o monte de Sião, e sobre o seu morro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 5, 'Tal como as aves voam [ao redor de seu ninho] ,assim o SENHOR dos exércitos protegerá a Jerusalém; por sua proteção ele a livrará, e por sua passagem ele a salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 6, 'Convertei-vos a aquele [contra quem] os filhos de Israel se rebelaram tão profundamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 7, 'Porque naquele dia cada um rejeitará seus ídolos de prata, e seus ídolos de ouro, que vossas mãos fizeram para vós pecardes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 8, 'E a Assíria cairá pela espada, mas não de homem; uma espada que não é humana a consumirá; e ela fugirá da espada, e seus rapazes serão submetidos a trabalhos forçados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 31, 9, 'Sua rocha se enfraquecerá de medo, e seus príncipes terão pavor da bandeira; [isto] diz o SENHOR, cujo fogo está em Sião, e sua fornalha em Jerusalém.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 1, 'Eis que um rei reinará com justiça, e príncipes governarão conforme o juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 2, 'E [cada] homem será como um abrigo contra o vento, e refúgio contra a tempestade; como ribeiros de águas em lugares secos, como a sombra de uma grande rocha num lugar deserto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 3, 'E os olhos dos que vem não se ofuscarão; e os ouvidos dos que ouvem estarão atentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 4, 'E o coração dos imprudentes entenderá o conhecimento, e a língua dos gagos estará pronta para falar com clareza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 5, 'Nunca mais o tolo será chamado de nobre, nem o avarento de generoso;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 6, 'Pois o tolo fala tolices, e seu coração opera maldade, para praticar perversidade e falar enganos contra o SENHOR, para deixar vazia a alma do faminto, e fazer com que o sedento não tenha o que beber.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 7, 'Os instrumentos do avarento são maléficos; ele trama planos malignos para destruir aos aflitos com palavras falsas, mesmo quando o pobre fala com justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 8, 'Mas o nobre pensa em coisas nobres, e em coisas nobres ele permanece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 9, 'Levantai-vos, mulheres que estais em repouso, e ouvi a minha voz; ó filhas, que estais tão confiantes, dai ouvidos às minhas palavras:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 10, 'Daqui a um ano e alguns dias, sereis perturbadas, vós, que estais tão confiantes; porque a produção de uvas não terá sucesso, e a colheita não virá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 11, 'Tremei vós que estais em repouso, e sede perturbadas, vós que estais tão confiantes; despi-vos, e ficai nuas, e vesti vossos lombos [com roupa de saco] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 12, 'Lamentai-vos batendo em vossos peitos por causa dos campos agradáveis e das vides frutíferas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 13, 'Por causa da terra do meu povo, [na qual] espinhos e cardos crescerão; e por causa das casas de alegria [na] cidade alegre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 14, 'Pois o palácio será abandonado, a cidade ruidosa ficará deserta; a colina e as torres de guarda serão esvaziadas para sempre, para alegria dos jumentos selvagens, e [servirão] de pasto para o gado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 15, 'Até que seja derramado sobre nós o Espírito do alto; então o deserto se tornará um lugar fértil, e o lugar fértil será considerado uma floresta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 16, 'E o juízo habitará no deserto, e a justiça morará no campo fértil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 17, 'E a consequência da justiça será paz; e o produto da justiça, repouso e segurança para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 18, 'E meu povo habitará na morada da paz, em moradias bem seguras, em tranquilos lugares de descanso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 19, '(Granizo, porém, derrubará a floresta, e a cidade será abatida).'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 32, 20, 'Bem-aventurados sois vós, os que semeais sobre todas as águas; [e] deixais livres os pés do boi e do jumento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 1, 'Ai de ti, assolador, que não foste assolado, e que enganas sem ter sido enganado! Quando terminares de assolar, tu é que serás assolado; quando terminares de enganar, então te enganarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 2, 'Ó SENHOR, tem misericórdia de nós! Em ti temos esperança. Que tu sejas nossa força nas madrugadas, e nossa salvação no tempo de aflição.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 3, 'Ao som do ruído estrondoso, fugirão; quando tu te levantas, as nações se dispersam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 4, 'Então, [nações] ,vossos despojos serão colhidos tal como os insetos colhem; tal como os gafanhotos saltam, assim saltarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 5, 'Exaltado é o SENHOR, pois habita nas alturas; ele encheu a Sião de juízo e justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 6, 'Ele é a segurança de teus tempos, e a fonte de tua salvação, sabedoria e conhecimento; o temor ao SENHOR é seu tesouro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 7, 'Eis que os embaixadores deles estão gritando de fora; os mensageiros de paz estão chorando amargamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 8, 'As estradas estão vazias, não há quem passe pelos caminhos; o pacto foi desfeito, cidades foram desprezadas, ninguém é considerado importante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 9, 'A terra lamenta e se definha; o Líbano se envergonha e se seca; Sarom se tornou com um deserto; e Basã e Carmelo foram sacudidos, [tiradas suas folhas] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 10, 'Agora eu me levantarei,diz o SENHOR; agora me elevarei; agora serei exaltado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 11, 'Concebestes palha, gerais restos de cascas; vosso sopro vos consumirá [como] o fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 12, 'E os povos serão [como] incêndios de cal; tal como espinhos cortados, eles se queimarão no fogo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 13, 'Vós que estais longe, ouvi o que eu tenho feito; e vós que estais perto, conhecei o meu poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 14, 'Os pecadores em Sião estão assombrados; o tremor tomou os perversos; [eles dizem] : Quem dentre nós pode conviver com o fogo consumidor? Quem dentre nós pode conviver com as labaredas eternas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 15, 'O que anda em justiça, e que fala o que é correto; que rejeita o ganho [proveniente] de opressões, que com suas mãos faz o gesto de “não” aos subornos, que tapa seus ouvidos para não ouvir sobre [crimes de] sangue, e fecha seus olhos para não ver o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 16, 'Este morará nas alturas; fortalezas de rochas serão seu abrigo; ele será provido de pão, [e] suas águas serão garantidas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 17, 'Teus olhos verão o rei em sua formosura; [e] verão uma terra que [se estende] até longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 18, 'Teu coração pensará sobre o assombro, dizendo: Onde está o escriba? Onde está o tesoureiro? Onde está o que contava as torres?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 19, 'Não verás [mais] aquele povo atrevido, povo de fala tão profunda, que não se pode compreender, de língua tão estranha, que não se pode entender.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 20, 'Olhai para Sião, a cidade de nossas solenidades; teus olhos verão Jerusalém, morada tranquila, tenda que não será derrubada, cujas estacas nunca serão arrancadas, e nenhuma de suas cordas se arrebentará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 21, 'Mas ali o SENHOR será grandioso para nós: ele será um lugar de rios [e] correntes largas; nenhum barco a remo passará por eles, nem navio grande navegará por eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 22, 'Pois o SENHOR é nosso juiz; o SENHOR é nosso legislador; o SENHOR é nosso Rei, ele nos salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 23, 'Tuas cordas se afrouxaram; não puderam manter firme o seu mastro, nem estenderam a vela; então uma grande quantidade de despojos será repartida; [até] os aleijados tomarão despojos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 33, 24, 'E nenhum morador dirá: Estou enfermo; [porque] o povo que nela habitar será perdoado de [sua] perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 1, 'Vós nações, achegai-vos para ouvir; e vós povos, escutai; que a terra ouça, e tudo quanto ela contém; o mundo, e tudo quanto ele produz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 2, 'Pois a ira do SENHOR [está] sobre todas as nações, e [seu] furor sobre todo os exércitos delas; ele as destruirá, e as entregará à matança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 3, 'E seus mortos serão lançados fora, e de seus corpos sairá seu fedor; e os montes se derreterão com seu sangue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 4, 'E todo o exército do céu se desfará, e os céus se enrolarão como um rolo de pergaminho; e todo o seu exército cairá, como cai a folha da vide, como cai [o figo] da figueira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 5, 'Pois minha espada se embebedou no céu; eis que descerá sobre Edom, sobre o povo a quem condenei à destruição, para o julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 6, 'A espada do SENHOR está cheia de sangue, está untada de gordura de sangue de cordeiros e de bodes, da gordura de rins de carneiros; porque o SENHOR tem sacrifício em Bozra, e grande matança na terra dos edomitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 7, 'E os bois selvagens descerão com eles, e os bezerros com os touros; e a terra deles beberá sangue até se fartar, e seu pó da terra de gordura será untado;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 8, 'Porque será o dia da vingança do SENHOR, ano de pagamentos pela briga contra Sião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 9, 'E seus ribeiros se tornarão em piche, e seu solo em enxofre; e sua terra em piche ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 10, 'Nem de noite, nem de dia se apagará, para sempre sua fumaça subirá; de geração em geração será assolada; para todo o sempre ninguém passará por ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 11, 'Mas o pelicano e a coruja tomarão posse dela, a ave selvagem e o corvo nela habitarão; pois[o SENHOR] estenderá sobre ela o cordel da assolação e o prumo da ruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 12, 'Chamarão ao seus nobres ao reino, porém nenhum haverá ali; e todos os seus príncipes se tornarão coisa nenhuma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 13, 'E em seus palácios crescerão espinhos; urtigas e cardos em suas fortalezas; e será habitação de chacais [e] habitação de avestruzes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 14, 'E os animais do deserto se encontrarão com os lobos, e o bode berrará ao seu companheiro; os animais noturnos ali pousarão, e acharão lugar de descanso para si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 15, 'Ali a coruja fará seu ninho e porá [ovos] ,e tirará seus filhotes, e os recolherá debaixo de sua sombra; também ali os abutres se ajuntarão uns com os outros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 16, 'Buscai no livro do SENHOR, e lede; nenhuma destas [criaturas] falhará, nenhuma destas faltará com sua companheira; pois de minha própria boca ele mandou, e seu próprio Espírito as ajuntará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 34, 17, 'Pois ele mesmo lhes deu terreno, e sua mão repartiu para elas com o cordel; para sempre terão posse dela, geração após geração nela habitarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 1, 'O deserto e o lugar seco terão prazer disto; e o lugar desabitado se alegrará e florescerá como a rosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 2, 'Abundantemente florescerá, e também se encherá de alegria e júbilo; a glória do Líbano lhe será dada, a honra do Carmelo e de Sarom; eles verão a glória do SENHOR, a honra de nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 3, 'Fortalecei as mãos fracas, e firmai os joelhos que tremem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 4, 'Dizei aos perturbados de coração: Fortalecei-vos! Não temais! Eis que nosso Deus virá para a vingança, aos pagamentos de Deus; ele virá e vos salvará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 5, 'Então os olhos dos cegos serão abertos, e os ouvidos dos surdos se abrirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 6, 'Então os aleijados saltarão como cervos, e a língua dos mudos falará alegremente; porque águas arrebentarão no deserto, e ribeiros no lugar desabitado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 7, 'E a terra seca se tornará em lagoas, e a terra sedenta em mananciais de águas; nas habitações em que repousavam os chacais, haverá erva com canas e juncos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 8, 'E ali haverá uma estrada, e um caminho que se chamará caminho da santidade; o impuro não passará por ele, mas será para os [que podem] andar pelo caminho; até mesmo os tolos [que por ele passarem] não errarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 9, 'Ali não haverá leão, nem animal selvagem subirá a ele, nem se achará nele; porém os redimidos [por ele] andarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 35, 10, 'E os resgatados do SENHOR voltarão, e virão a Sião com júbilo, e alegria eterna haverá sobre suas cabeças; eles terão prazer e alegria, e a tristeza e o gemido [deles] fugirão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 1, 'E aconteceu no décimo quarto ano do rei Ezequias, que Senaqueribe, rei da Assíria, subiu contra todas as cidades fortificadas de Judá, e as tomou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 2, 'Então o rei da Assíria enviou a Rabsaqué, de Laquis a Jerusalém, ao rei Ezequias, com um grande exército; e ele parou junto ao duto do tanque superior, junto ao caminho do campo do lavandeiro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 3, 'Então saíram ao encontro dele Eliaquim, filho de Hilquias, o administrador da casa real; Sebna, o escriba, e Joá, filho de Asafe, o cronista.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 4, 'E [Rabsaqué] lhes disse: Dizei, pois, a Ezequias: Assim diz o grande rei, o rei da Assíria: Que confiança é essa, em que confias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 5, 'Eu, de fato, digo, que [teus] conselhos e poder de guerra são apenas palavras vazias. Em quem, pois, confias, para te rebelares contra mim?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 6, 'Eis que confias no Egito, aquele bastão de cana quebrada, em quem se alguém se apoiar, entrará pela mão e a perfurará; assim é Faraó, rei do Egito, para com todos os que nele confiam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 7, 'Porém, se me disseres: Confiamos no SENHOR, nosso Deus; Por acaso não é este aquele cujos altos e cujos altares Ezequias tirou, e disse a Judá e a Jerusalém: Perante este altar adorareis?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 8, 'Agora, pois, submeta-te à proposta do meu senhor, o rei da Assíria; e eu te darei dois mil cavalos, se tu podes dar dois mil cavaleiros para eles.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 9, 'Como, pois, te oporias a um chefe dentre os menores servos do meu senhor, [apenas] confiando nas carruagens e cavaleiros do Egito?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 10, 'Ora, subi eu sem o SENHOR contra esta terra, para destruí-la? O [próprio] SENHOR me disse: Sobe contra esta terra, e destrói-a.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 11, 'Então Eliaquim, Sebna e Joá disseram a Rabsaqué: Pedimos que fale a teus servos em aramaico, porque nós o entendemos; e não nos fale na língua judaica, aos ouvidos do povo, que está sobre o muro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 12, 'Porém Rabsaqué disse: Por acaso meu senhor me mandou falar estas palavras [só] a teu senhor e a ti, e não [também] aos homens que estão sentados sobre o muro, que juntamente convosco comerão suas próprias fezes, e beberão sua própria urina?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 13, 'Então Rabsaqué se pôs de pé, clamou em alta voz na língua judaica, e disse: Ouvi as palavras do grande rei, o rei da Assíria!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 14, 'Assim diz o rei: Que Ezequias não vos engane, pois ele não poderá vos livrar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 15, 'Nem deixeis que Ezequias vos faça confiar no SENHOR, dizendo: Com certeza o SENHOR nos livrará; esta cidade não será entregue nas mãos do rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 16, 'Não escuteis a Ezequias; porque assim diz o rei da Assíria: fazei as pazes comigo, e saí até mim; e cada um com de sua vide, e de sua figueira, e cada um beba a água de sua [própria] cisterna;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 17, 'Até que eu venha, e vos leve a uma terra como a vossa, terra de trigo e de suco de uva, terra de pão e de vinhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 18, 'Que Ezequias não vos engane, dizendo: O SENHOR nos livrará; por acaso os deuses das nações livraram cada um sua terra das mãos do rei da Assíria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 19, 'Onde estão os deuses de Hamate e de Arpade? Onde estão os deuses de Sefarvaim? Por acaso eles livraram a Samaria das minhas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 20, 'Quem são dentre todos os deuses destas terras, que livraram sua terra das minhas mãos? Como, pois, o SENHOR livrará a Jerusalém das minhas mãos?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 21, 'Porém eles ficaram calados, e nenhuma palavra lhe responderam; porque tinham ordem do rei, dizendo: Não lhe respondereis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 36, 22, 'Então Eliaquim, filho de Hilquias, o administrador da casa real, e Sebna, o escriba, e Joá filho de Asafe, o cronista, vieram a Ezequias com as roupas rasgadas, e lhe contaram as palavras de Rabsaqué.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 1, 'E aconteceu que, quando o rei Ezequias ouviu [isso] ,ele rasgou suas roupas, cobriu-se de saco, e entrou na casa do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 2, 'Então ele enviou Eliaquim o administrador da casa real, Sebna o escriba, e os anciãos dos sacerdotes, cobertos de sacos, ao profeta Isaías, filho de Amoz.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 3, 'E lhe disseram: Assim diz Ezequias: Este dia é um dia de angústia, de repreensão, e de blasfêmia; pois os filhos chegaram ao parto, porém não há força para que possam nascer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 4, 'Talvez o SENHOR venha a ouvir as palavras de Rabsaqué, a quem seu senhor, o rei da Assíria, enviou, para afrontar ao Deus vivente; e repreenda as palavras que o SENHOR teu Deus tem ouvido. Faze, pois, oração pelos restantes, que [ainda] se encontram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 5, 'E os servos do rei vieram até Isaías,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 6, 'E Isaías lhes disse: Assim direis a vosso senhor: Assim diz o SENHOR: Não temas das palavras que ouviste, com as quais os servos do rei da Assíria me blasfemaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 7, 'Eis que porei nele um espírito de tal maneira que, quando ouvir um rumor, ele voltará à sua terra; e eu o derrubarei pela espada em sua [própria] terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 8, 'Então Rabsaqué voltou, e achou ao rei da Assíria lutando contra Libna, pois tinha ouvido que ele [já] tinha saído de Laquis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 9, 'E ele, ao ouvir dizer que Tiraca, rei de Cuxe, tinha saído para fazer guerra contra ele, então, após ouvir, enviou mensageiros a Ezequias, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 10, 'Assim falareis a Ezequias, rei de Judá, dizendo: Que teu Deus, em quem confias, não te engane, dizendo: Jerusalém não será entregue nas mãos do rei da Assíria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 11, 'Eis que tens ouvido o que os reis da Assíria fizeram a todas as terras, destruindo-as por completo. E tu, escaparias?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 12, 'Por acaso as livraram os deuses das nações as quais meus pais destruíram, tal como Gozã, Harã e Rezefe, e os filhos de Éden que estavam em Telassar?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 13, 'Onde está o rei da Hamate, o rei de Arpade, o rei de Sefarvaim, ou Hena e Iva?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 14, 'E Ezequias, recebendo as cartas das mãos dos mensageiros, e tendo as lido, subiu à casa do SENHOR, e Ezequias as estendeu perante o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 15, 'Então Ezequias orou ao SENHOR, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 16, 'Ó SENHOR dos exércitos, Deus de Israel, que habitas entre os querubins; tu, só tu, és Deus de todos os reinos da terra; tu fizeste os céus e a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 17, 'Inclina teu ouvido, ó SENHOR, e ouve; abre os teus olhos, SENHOR, e olha; e ouve todas as palavras de Senaqueribe que ele enviou para afrontar o Deus vivente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 18, 'É verdade, SENHOR, que os reis da Assíria assolaram a todas as terras e seus territórios,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 19, 'E lançaram seus deuses ao fogo, porque não eram deuses, mas sim obras de mãos humanas, madeira e pedra; por isso os destruíram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 20, 'Agora, SENHOR nosso Deus, livra-nos das mãos dele, [e] assim todos os reinos da terra saberão que tu, só tu, és o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 21, 'Então Isaías, filho de Amós, mandou dizer a Ezequias: Assim diz o SENHOR, Deus de Israel: Quanto ao que me pediste sobre Senaqueribe, rei da Assíria,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 22, 'Esta é a palavra que o SENHOR falou sobre ele: A virgem, a filha de Sião, te despreza, zomba de ti; a filha de Jerusalém balança a cabeça após ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 23, 'A quem afrontaste? [De quem] blasfemaste? E contra quem levantaste a voz, e levantaste aos olhos arrogantemente? Contra o Santo de Israel!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 24, 'Por meio de teus servos afrontaste ao Senhor, e disseste: Com a minha multidão de carruagens eu subi aos cumes dos montes, aos lugares remotos do Líbano; e cortarei seus altos cedros, e seus melhores ciprestes, e virei a seu extremo cume, ao bosque de seu campo fértil.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 25, 'Eu cavei, e bebi as águas; e com as plantas dos meus pés secarei todos os rios do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 26, 'Por acaso não ouviste que desde muito antes eu fiz isto, e deste os dias antigos o tinha planejado? Agora eu fiz isto acontecer, para que tu fosses o que destruirias as cidades fortificadas, [reduzindo-as] a amontoados de ruínas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 27, 'Por isso os moradores delas, com as mãos impotentes, ficaram atemorizados e envergonhados; eram [como] a erva do campo, e a grama verde, o capim dos telhados e o trigo queimado antes de crescer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 28, 'Porém eu sei o teu sentar, o teu sair, o teu entrar, e o teu furor contra mim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 29, 'Por causa de teu furor contra mim, e teu tumulto que subiu aos meus ouvidos, por isso porei meu anzol em teu nariz, e meu freio em tua boca; e te farei voltar pelo caminho em que vieste.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 30, 'E isto será por sinal para ti, [Ezequias] : este ano se comerá daquilo que nascer de si mesmo, e no segundo ano do que daí proceder; porém no terceiro ano semeai e colhei; e plantai vinhas, e comei seus frutos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 31, 'Pois os sobreviventes da casa de Judá, o remanescente, voltará a formar raízes abaixo, e dará fruto acima.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 32, 'Porque de Jerusalém sairá o remanescente, e do monte de Sião os que sobreviverem; o zelo do SENHOR dos exércitos fará isto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 33, 'Portanto assim diz o SENHOR quanto ao rei da Assíria: Ele não entrará nesta cidade, nem lançará flecha nela; nem também virá diante dela com escudo, nem levantará cerco contra ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 34, 'Pelo mesmo caminho que veio, nele voltará; mas nesta cidade ele não entrará, diz o SENHOR;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 35, 'Porque eu defenderei esta cidade para a livrar, por causa de mim e por causa do meu servo Davi.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 36, 'Então o anjo do SENHOR saiu, e feriu no acampamento dos assírios cento e oitenta mil [deles] ; e levantando-se pela manhã cedo, eis que todos eram cadáveres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 37, 'Assim Senaqueribe, rei da Assíria, partiu-se, e foi embora, voltou, e ficou em Nínive.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 37, 38, 'E sucedeu que, enquanto ele estava prostrado na casa de seu deus Nisroque, seus filhos Adrameleque e Sarezer o feriram a espada; então eles escaparam para a terra de Ararate; e Esar-Hadom, seu filho, reinou em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 1, 'Naqueles dias Ezequias ficou doente, perto de morrer. E veio até ele Isaías, filho de Amoz, e lhe disse: Assim diz o SENHOR: Põe em ordem a tua casa, porque morrerás, e não viverás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 2, 'Então Ezequias virou o seu rosto para a parede, e orou ao SENHOR,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 3, 'E disse: Ó SENHOR, lembra-te, eu te peço, de que andei diante de ti com fidelidade e com coração íntegro, e fiz o que era agradável aos teus olhos! E Ezequias chorou com muito lamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 4, 'Então veio a palavra do SENHOR a Isaías, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 5, 'Vai, e diz a Ezequias: Assim diz o SENHOR, o Deus de teu pai Davi: Eu ouvi tua oração, [e] vi tuas lágrimas. Eis que acrescento quinze anos aos teus dias [de vida] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 6, 'E das mãos do rei da Assíria eu livrarei a ti, e a esta cidade; e defenderei esta cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 7, 'E isto te será por sinal da parte do SENHOR, de que o SENHOR cumprirá esta palavra que falou:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 8, 'Eis que voltarei voltar a sombra dos degraus nos quais o sol desceu na escadaria de Acaz; dez degraus atrás.Assim voltou o sol dez degraus, pelos degraus que já tinha descido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 9, 'Escritura de Ezequias, rei de Judá, quando ficou doente, e se sarou de sua enfermidade:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 10, 'Disse eu: No meio da minha vida, irei às portas do Xeol; privado estou do resto dos meus anos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 11, 'Eu disse: Não verei [mais] ao SENHOR, o SENHOR na terra dos viventes; não mais olharei aos homens com os que habitam o mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 12, 'Minha morada foi removida e tirada de mim, como uma tenda de pastor; enrolei minha vida como um tecelão; ele me cortará fora do tear; desde o dia até a noite tu me acabarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 13, 'Fiquei esperando até a manhã; como um leão ele quebrou todos os meus ossos; desde o dia até a noite tu me acabarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 14, 'Como o grou, [ou] a andorinha, assim eu fazia barulho; [e] gemia como uma pomba; ao alto eu levantava meus olhos. Ó SENHOR, estou oprimido! Sê tu minha segurança!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 15, 'Que direi? Tal como ele me falou, assim fez; passarei lentamente por todos os meus anos, por causa da amargura de minha alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 16, 'Ó Senhor, por estas coisas é que se vive, e em todas elas está a vida de meu espírito. Então cura-me, e deixa-me viver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 17, 'Eis que para meu [próprio] bem tive grande amargura; tu, porém, com amor livraste minha alma da cova do perecimento; porque lançaste para trás de ti todos os meus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 18, 'Porque o Xeol não te louvará, [nem] a morte te glorificará; nem esperarão em tua fidelidade os que descem a cova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 19, 'O vivente, o vivente, esse é o que te louvará, tal como hoje eu faço; o pai ensinará aos filhos tua fidelidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 20, 'O SENHOR tem me salvado! Por isso tocaremos canções com instrumentos de cordas todos os dias de nossa vida na casa do SENHOR!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 21, 'Pois Isaías havia dito: Tomem uma pasta de figos, e passem-na sobre a inflamação, que ele sarará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 38, 22, 'Ezequias também tinha dito: Qual será o sinal de que subirei à casa do SENHOR?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 1, 'Naquele tempo, Merodaque-Baladã, filho de Baladã, rei da Babilônia, enviou [mensageiros com] cartas e um presente a Ezequias, porque tinha ouvido que ele havia ficado doente e já tinha se curado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 2, 'E Ezequias se alegrou com eles, e lhes mostrou a casa de teu tesouro, a prata, o ouro, as especiarias, os melhores óleos, e toda a sua casa de armas, e tudo quanto se achou em seus tesouros; coisa nenhuma houve, nem em sua casa, nem em todo o seu domínio, que Ezequias não lhes mostrasse.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 3, 'Então o profeta Isaías veio ao rei Ezequias, e lhe disse: O que aqueles homens disseram? E de onde eles vieram a ti?E Ezequias disse: Eles vieram a mim de uma terra distante, da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 4, 'E ele lhe disse: O que viram em tua casa?E Ezequias disse: Eles viram tudo quanto há em minha casa; coisa nenhuma há em meus tesouros que eu não tenha lhes mostrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 5, 'Então Isaías disse a Ezequias: Ouve a palavra do SENHOR dos exércitos:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 6, 'Eis que vem dias em que tudo quanto houver em tua casa, e que teus pais acumularam até o dia de hoje, será levado à Babilônia; nada restará, diz o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 7, 'E [até] de teus filhos, que procederem de ti, e tu gerares, tomarão; e eles serão eunucos no palácio do rei da Babilônia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 39, 8, 'Então Ezequias disse a Isaías: Boa é a palavra do SENHOR que falaste.Disse também: Pois haverá paz e segurança em meus dias.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 1, 'Consolai, consolai a meu povo, diz vosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 2, 'Falai ao coração de Jerusalém, e proclamai a ela, que seu esforço de guerra está terminado, que sua perversidade está perdoada; porque já recebeu [punição] em dobro da mão do SENHOR por todo os seus pecados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 3, 'Voz do que clama no deserto: Preparai o caminho do SENHOR; endireitai na terra estéril vereda ao nosso Deus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 4, 'Todo vale será levantado, e todo monte e morro serão abaixados; e o torto se endireitará, e o [terreno] acidentado se tornará plano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 5, 'E a glória do SENHOR se manifestará; e toda carne juntamente verá; pois [assim] falou a boca do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 6, 'Uma voz: Clama!E ele disse: O que clamarei? Que toda carne é erva, e toda a sua bondade como as flores do campo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 7, 'A erva se seca, as flores caem, porque o Espírito do SENHOR nelas sopra; verdadeiramente o povo é erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 8, 'A erva se seca, as flores caem; porém a palavra do nosso Deus continua firme para sempre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 9, 'Ó Sião, que anuncias boas novas, sobe até um monte alto! Ó Jerusalém, que anuncias boas novas, levanta tua voz com força; levanta-a, não temas; dize as cidades de Judá: Eis [aqui] o vosso Deus!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 10, 'Eis que o Senhor DEUS virá com poder; e seu braço governará por ele; eis que sua retribuição [virá] com ele, e seu pagamento diante de si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 11, 'Como pastor ele apascentará seu rebanho; em seus braços recolherá aos cordeirinhos, e os levará em seu colo; ele guiará mansamente as que tiveram filhotes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 12, 'Quem mediu com seu punho as águas, e tomou a medida dos céus aos palmos? E [quem] recolheu numa caixa de medida o pó da terra, e pesou os montes com pesos, e os morros com balanças?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 13, 'Quem guiou o Espírito do SENHOR? E que conselheiro o ensinou?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 14, 'Com quem ele tomou conselho? [Quem] lhe deu entendimento, e lhe ensinou o caminho do juízo, e lhe ensinou conhecimento, e lhe mostrou o caminho do entendimento?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 15, 'Eis que as nações [lhe] são consideradas como uma gota de balde, e como o pó miúdo das balanças; eis que ele levanta as ilhas como poeira.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 16, 'Nem [todo] o Líbano seria suficiente para o fogo, nem seus animais bastam para um holocausto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 17, 'Todas as nações são como nada perante ele; menos que nada e vazio ele as considera.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 18, 'A quem, pois, comparareis a Deus? Ou que semelhança atribuireis a ele?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 19, 'O artífice funde a imagem, e o ourives a cobre de ouro, e cadeias de prata [lhe] funde.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 20, 'O empobrecido, que não tem o que oferecer, escolhe madeira que não se estraga, [e] busca um artífice habilidoso, para preparar uma imagem que não se mova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 21, 'Por acaso não sabeis? Por acaso não ouvis? Ou desde o princípio não vos disseram? Por acaso não tendes entendido desde os fundamentos da terra?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 22, 'Ele é o que está sentado sobre o globo da terra, cujos moradores são [para ele] como gafanhotos; ele é o que estende os céus como uma cortina, e os estica como uma tenda, para [neles] habitar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 23, 'Ele é o que torna os príncipes em nada, [e] faz juízes da terra serem como o vazio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 24, 'Mal foram plantados, mal foram semeados, mal seu caule forma raízes na terra; e [logo] ele sopra neles, e se secam, e um vento forte os leva como palha fina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 25, 'A quem, pois, me comparareis, que eu lhe seja semelhante?,diz o Santo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 26, 'Levantai vossos olhos ao alto, e vede quem criou estas coisas, que faz sair numerado seu exército; e chama a todos eles pelos nomes, pela grandeza de [suas] forças, e por ser forte em poder, nenhuma [delas] faltará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 27, 'Por que dizes, ó Jacó, e falas, ó Israel: Meu caminho está escondido do SENHOR, e meu juízo passa longe de meu Deus?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 28, 'Por acaso não sabes, nem ouviste, que o eterno Deus, o SENHOR, o criador dos confins da terra, não se cansa, nem se fatiga, e que seu entendimento é incompreensível?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 29, 'Ele dá força ao cansado, e multiplica as forças daquele que não tem vigor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 30, 'Até os jovens se cansam e se fatigam; e os rapazes caem;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 40, 31, 'Mas os que confiam no SENHOR renovarão as forças, subirão com asas como águias; correrão, e não se cansarão; caminharão, e não se fatigarão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 1, 'Calai-vos perante mim, ó litorais; e os povos renovem as forças; aproximem-se, [e] então falem; juntamente nos aproximemos ao juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 2, 'Quem o chamou desde o oriente, [e com] justiça o chamou ao seu pé? Ele [lhe] deu as nações perante sua face, e o fez dominar sobre reis, [e] os entregou à sua espada como o pó, como a palha fina levada por seu arco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 3, 'Ele os persegue, [e] passa em segurança; por um caminho [onde] com seus pés nunca tinha ido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 4, 'Quem operou e fez [isto] ,chamando as gerações desde o princípio? Eu, o SENHOR, do princípio aos últimos, eu mesmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 5, 'Os litorais viram, e tremeram; os confins da terra tremeram; eles se aproximaram, e chegaram.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 6, 'Cada um ajudou ao outro, e a seu companheiro disse: Sê forte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 7, 'E o artífice encorajou ao ourives, o que alisa com o martelo ao que bate na bigorna, dizendo da soldagem: Boa é. Então com pregos o firmou, para que não se mova.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 8, 'Porém tu, ó Israel, servo meu; tu, Jacó, a quem escolhi, semente de Abraão, meu amigo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 9, 'Tu, a quem tomei desde os confins da terra, e te chamei desde seus mais extremos, e te disse: Tu és meu servo; a ti escolhi, e não te rejeitei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 10, 'Não temas, porque eu estou contigo; não te assombres, porque eu sou teu Deus. Eu te fortaleço, te ajudo, e te sustento com a minha mão direita de justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 11, 'Eis que serão envergonhados e humilhados todos os que se indignaram contra ti; eles se tornarão como o nada; e os que brigarem contigo perecerão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 12, '[Ainda que] os procures, tu não os acharás; os que lutarem contra ti se tornarão como o nada; e os que guerrearem contra ti, como coisa nenhuma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 13, 'Porque eu, o SENHOR teu Deus, te seguro pela tua mão direita, [e] te digo: Não temas; eu te ajudo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 14, 'Não temas, ó verme de Jacó, povinho de Israel; eu te ajudo,diz o SENHOR e teu Redentor, o Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 15, 'Eis que eu te pus como debulhador afiado, novo, que tem dentes pontiagudos. Aos montes debulharás, e moerás; e aos morros tornarás como a palhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 16, 'Tu os padejarás, e o vento os levará; e o redemoinho os espalhará; porém tu te alegrarás no SENHOR, [e] te orgulharás no Santo de Israel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 17, 'Os pobres e necessitados buscam águas, mas nada [acham] ; sua língua se seca de sede. Eu, o SENHOR, os ouvirei; eu, o Deus de Israel, não os desampararei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 18, 'Abrirei rios em lugares altos, e fontes no meio dos vales; tornarei o deserto em tanques de águas, e a terra seca em mananciais de águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 19, 'Plantarei no deserto o cedro, a acácia, a murta, e a oliveira; juntamente porei na terra vazia a faia, o olmeiro e o cipreste;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 20, 'Para que vejam, saibam, reflitam, e juntamente entendam que a mão do SENHOR fez isto; e o Santo de Israel isto criou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 21, 'Apresentai vossa demanda!,diz o SENHOR. Trazei vossos argumentos!, diz o Rei de Jacó.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 22, 'Tragam e anunciem-nos as coisas que irão acontecer; anunciai quais foram as coisas passadas, para que possamos dar atenção a elas, e saibamos o fim delas; ou dizei-nos as coisas futuras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 23, 'Anunciai as coisas que ainda virão, para que saibamos que vós sois deuses; ou fazei o bem ou o mal, para que nos assombremos, e juntamente vejamos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 24, 'Eis que vós sois nada, e vossa obra não tem valor algum; abominação é quem vos escolhe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 25, 'Eu suscitei [a um] do norte, que virá oriente, [e] invocará meu nome; e virá sobre os príncipes como [se fossem] lama, e como o oleiro pisa o barro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 26, 'Quem anunciou [coisa alguma] desde o princípio, para que o possamos saber, ou desde antes, para que digamos “correto é”? Porém não há quem anuncie [tal coisa] nem quem diga [coisa alguma] , nem quem ouça vossas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 27, '[Eu sou] o primeiro [que digo] a Sião: Eis que ali estão! E a Jerusalém darei um anunciador de boas novas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 28, 'E olhei, porém ninguém havia. Até entre estes nenhum conselheiro havia a quem eu perguntasse, e ele me respondesse algo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 41, 29, 'Eis que todos são falsidade, suas obras são nada. Suas obras de fundição são vento e sem valor algum.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 1, 'Eis aqui meu servo, a quem sustento; meu escolhido, [em quem] minha alma se agrada. Sobre ele eu pus o meu Espírito; ele trará justiça às nações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 2, 'Ele não gritará, nem levantará [seu clamor] ; ele não fará ouvir sua voz nas ruas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 3, 'A cana rachada ele não quebrará, nem apagará o pavio que fumega; com a verdade ele trará justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 4, 'Ele não fraquejará, nem será esmagado, até que ponha a justiça na terra; e os litorais esperarão a sua doutrina.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 5, 'Assim diz Deus, o SENHOR, que criou os céus, e os esticou; estendeu a terra, e a tudo quanto ela produz; que dá respiração ao povo que nela [habita] ,e espírito aos que nela andam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 6, 'Eu, o SENHOR, te chamei em justiça, e te tomarei pela mão. E eu te guardarei, e te darei como pacto para o povo e luz para as nações;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 7, 'Para abrir os olhos cegos, para tirar da prisão os presos, [tirar] do cárcere os que habitam em trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 8, 'Eu, EU-SOU; este é o meu nome! Não darei a minha glória a outro, nem o meu louvor às imagens de escultura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 9, 'Eis que as coisas anteriores já aconteceram; e as novas eu [vos] anuncio; e antes que surjam, [delas] eu vos informo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 10, 'Cantai ao SENHOR um cântico novo, um louvor a ele desde o limite da terra; vós que navegais pelo mar, e tudo quanto nele há; vós terras do litoral e seus moradores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 11, 'Levantem [a voz] o deserto e suas cidades, com as aldeias que Quedar habita; cantem os que habitam nas rochas, [e] gritem de alegria do cume dos montes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 12, 'Deem glória ao SENHOR, e anunciem louvor a ele nas terras do litoral.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 13, 'O SENHOR sairá como guerreiro, como homem de guerra despertará o [seu] zelo; ele gritará, e fará grade ruído; e dominará a seus inimigos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 14, 'Por muito tempo fiquei calado, quieto estive, [e] me retive; [mas agora] darei gritos como a que está de parto, suspirando e juntamente ofegando.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 15, 'Aos montes e morros tornarei em deserto, e toda sua erva farei secar; e tornarei aos rios em ilhas, e as lagoas secarei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 16, 'E guiarei aos cegos por um caminho que nunca conheceram; eu os farei caminhar pelas veredas que não conheciam; tornarei as trevas em luz perante eles, e as coisas tortas [farei] direitas; estas coisas lhes farei, e nunca os desampararei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 17, '[Mas] serão conduzidos para trás e se envergonharão os que confiam em imagens de escultura, [e] dizem às imagens de fundição: Vós sois nossos deuses.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 18, 'Surdos, ouvi; e vós cegos, olhai para que possais ver.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 23, 'Isaías', 'Is', 42, 19, 'Quem é cego, senão o meu servo? Ou surdo, como o meu mensageiro, a quem envio? Quem é cego como o aliançado, e cego como o servo do SENHOR?')
